from __future__ import annotations


class Group:
    def __init__(self, members: list[str]) -> None:
        if not members:
            raise ValueError("Group must have at least one member")
        # preserve order, remove duplicates? Keep as-is but ensure uniqueness
        self.members = list(dict.fromkeys(members))
        self._balances: dict[str, float] = {m: 0.0 for m in self.members}

    def _require_member(self, name: str) -> None:
        if name not in self._balances:
            raise ValueError(f"{name!r} is not a member of the group")

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if amount <= 0:
            raise ValueError("amount must be positive")
        self._require_member(payer)

        if participants is None:
            parts = list(self.members)
        else:
            parts = list(participants)
            if not parts:
                raise ValueError("participants must be non-empty")
            for p in parts:
                self._require_member(p)

        # Each participant's share, rounded down to the cent;
        # the payer absorbs any leftover cents.
        n = len(parts)
        total_cents = round(amount * 100)
        # Integer division gives floor per-participant share
        base_cents = total_cents // n
        # Payer's share absorbs the remainder (may be larger)
        payer_share_cents = total_cents - base_cents * (n - 1)

        # Payer paid the whole amount
        self._balances[payer] += amount

        for p in parts:
            if p == payer:
                share = payer_share_cents / 100.0
            else:
                share = base_cents / 100.0
            self._balances[p] -= share

        # Re-round to remove floating point drift
        for m in self._balances:
            self._balances[m] = round(self._balances[m], 10)

    def balances(self) -> dict[str, float]:
        # Round to cents for display consistency
        return {m: round(v + 0.0, 2) for m, v in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        # Work in integer cents to avoid floating point issues
        cents = {m: int(round(v * 100)) for m, v in self._balances.items()}

        debtors = sorted(
            [(m, -c) for m, c in cents.items() if c < 0],
            key=lambda x: (-x[1], x[0]),
        )
        creditors = sorted(
            [(m, c) for m, c in cents.items() if c > 0],
            key=lambda x: (-x[1], x[0]),
        )

        payments: list[tuple[str, str, float]] = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            debtor, owes = debtors[i]
            creditor, due = creditors[j]
            pay = min(owes, due)
            if pay > 0:
                payments.append((debtor, creditor, pay / 100.0))
            owes -= pay
            due -= pay
            if owes == 0:
                i += 1
            else:
                debtors[i] = (debtor, owes)
            if due == 0:
                j += 1
            else:
                creditors[j] = (creditor, due)

        return payments
